import redis
from collections import defaultdict

SRC_HOST, SRC_PORT = "127.0.0.1", 6379
DST_HOST, DST_PORT = "127.0.0.1", 6380

def dbs_with_keys(r):
    ks = r.info("keyspace") or {}
    return sorted(int(k[2:]) for k in ks if k.startswith("db") and (ks[k] or {}).get("keys", 0) > 0)

def copy_key(s, d, key, typ):
    if typ == b"string":
        v = s.execute_command("GET", key)
        d.execute_command("SET", key, v)
    elif typ == b"list":
        vals = s.execute_command("LRANGE", key, 0, -1)
        if vals:
            d.execute_command("RPUSH", key, *vals)
    elif typ == b"set":
        members = s.execute_command("SMEMBERS", key)
        if members:
            d.execute_command("SADD", key, *members)
    elif typ == b"zset":
        flat = s.execute_command("ZRANGE", key, 0, -1, "WITHSCORES")
        args = []
        for i in range(0, len(flat), 2):
            args.append(flat[i+1]); args.append(flat[i])  # score member
        if args:
            d.execute_command("ZADD", key, *args)
    elif typ == b"hash":
        items = s.execute_command("HGETALL", key)
        if items:
            d.execute_command("HSET", key, *items)
        # field-level TTLs
        fields = [items[i] for i in range(0, len(items), 2)]
        if fields:
            exp = s.execute_command("HPEXPIRETIME", key, "FIELDS", len(fields), *fields)
            for f, e in zip(fields, exp):
                e = int(e)
                if e > 0:
                    d.execute_command("HPEXPIREAT", key, e, "FIELDS", 1, f)
    elif typ == b"stream":
        copy_stream(s, d, key)
    else:
        raise RuntimeError(f"unsupported type {typ} for key {key!r}")

def copy_stream(s, d, key):
    entries = s.execute_command("XRANGE", key, "-", "+")
    pipe = d.pipeline(transaction=False)
    for mid, fields in entries:
        args = []
        for f, v in fields.items():
            args.append(f); args.append(v)
        pipe.execute_command("XADD", key, mid, *args)
    pipe.execute()

    groups = s.execute_command("XINFO", "GROUPS", key)
    for g in groups:
        gd = {g[i]: g[i+1] for i in range(0, len(g), 2)}
        gname = gd[b"name"]
        last = gd[b"last-delivered-id"]
        d.execute_command("XGROUP", "CREATE", key, gname, last)
        consumers = s.execute_command("XINFO", "CONSUMERS", key, gname)
        cnames = []
        for c in consumers:
            cd = {c[i]: c[i+1] for i in range(0, len(c), 2)}
            cnames.append(cd[b"name"])
            d.execute_command("XGROUP", "CREATECONSUMER", key, gname, cd[b"name"])
        pel = s.execute_command("XPENDING", key, gname, "-", "+", 1000000)
        byc = defaultdict(list)
        for row in pel:
            mid, consumer = row[0], row[1]
            byc[consumer].append(mid)
        for cname, ids in byc.items():
            d.execute_command("XCLAIM", key, gname, cname, 0, *ids, "FORCE", "JUSTID")

def main():
    src = redis.Redis(host=SRC_HOST, port=SRC_PORT, decode_responses=False)
    dst = redis.Redis(host=DST_HOST, port=DST_PORT, decode_responses=False)
    total = 0
    for db in dbs_with_keys(src):
        s = redis.Redis(host=SRC_HOST, port=SRC_PORT, db=db, decode_responses=False)
        d = redis.Redis(host=DST_HOST, port=DST_PORT, db=db, decode_responses=False)
        keys = list(s.scan_iter(count=1000))
        # gather type + abs expire
        pipe = s.pipeline(transaction=False)
        for k in keys:
            pipe.execute_command("TYPE", k)
            pipe.execute_command("PEXPIRETIME", k)
        meta = pipe.execute()
        for i, k in enumerate(keys):
            typ = meta[2*i]
            if typ == b"none":
                continue
            pexp = int(meta[2*i+1])
            copy_key(s, d, k, typ)
            if pexp > 0:
                d.execute_command("PEXPIREAT", k, pexp)
        total += len(keys)
        print(f"db{db}: copied {len(keys)} keys")
    print("done, total keys scanned:", total)

if __name__ == "__main__":
    main()
