    ks = r.info("keyspace") or {}
    return sorted(int(k[2:]) for k in ks if k.startswith("db") and (ks[k] or {}).get("keys", 0) > 0)

def copy_key(s, d, key, typ):
    if typ == "string":
        d.set(key, s.get(key))
    elif typ == "list":
        vals = s.lrange(key, 0, -1)
        if vals:
            d.rpush(key, *vals)
    elif typ == "set":
        members = list(s.smembers(key))
        if members:
            d.sadd(key, *members)
    elif typ == "zset":
        pairs = s.zrange(key, 0, -1, withscores=True)
        if pairs:
            d.zadd(key, {m: sc for m, sc in pairs})
    elif typ == "hash":
        h = s.hgetall(key)
        if h:
            d.hset(key, mapping=h)
        fields = list(h.keys())
        if fields:
            exps = s.execute_command("HPEXPIRETIME", key, "FIELDS", len(fields), *fields)
            for f, e in zip(fields, exps):
                e = int(e)
                if e > 0:
                    d.execute_command("HPEXPIREAT", key, e, "FIELDS", 1, f)
    elif typ == "stream":
        copy_stream(s, d, key)
    else:
        raise RuntimeError(f"unsupported type {typ!r} for key {key!r}")

def copy_stream(s, d, key):
    for mid, fields in s.xrange(key, "-", "+"):
        args = []
        for f, v in fields.items():
            args.append(f); args.append(v)
        d.execute_command("XADD", key, mid, *args)

    for g in s.xinfo_groups(key):
        gname = g["name"]
        last = g["last-delivered-id"]
        d.execute_command("XGROUP", "CREATE", key, gname, last)
        for c in s.xinfo_consumers(key, gname):
            d.execute_command("XGROUP", "CREATECONSUMER", key, gname, c["name"])
        # pending entries, grouped by consumer
        byc = {}
        pel = s.xpending_range(key, gname, min="-", max="+", count=1000000)
        for row in pel:
            byc.setdefault(row["consumer"], []).append(row["message_id"])
        for cname, ids in byc.items():
            d.execute_command("XCLAIM", key, gname, cname, 0, *ids, "FORCE", "JUSTID")

def main():
    src = redis.Redis(host=SRC_HOST, port=SRC_PORT, decode_responses=False)
    total = 0
    for db in dbs_with_keys(src):
        s = redis.Redis(host=SRC_HOST, port=SRC_PORT, db=db, decode_responses=False)
        d = redis.Redis(host=DST_HOST, port=DST_PORT, db=db, decode_responses=False)
        keys = list(s.scan_iter(count=1000))
        pipe = s.pipeline(transaction=False)
        for k in keys:
            pipe.type(k)
            pipe.execute_command("PEXPIRETIME", k)
        meta = pipe.execute()
        copied = 0
        for i, k in enumerate(keys):
            typ = meta[2*i]
            if isinstance(typ, bytes):
                typ = typ.decode()
            if typ == "none":
                continue
            pexp = int(meta[2*i+1])
            copy_key(s, d, k, typ)
            if pexp > 0:
                d.execute_command("PEXPIREAT", k, pexp)
            copied += 1
        total += copied
        print(f"db{db}: copied {copied} keys")
    print("done, total keys copied:", total)

if __name__ == "__main__":
    main()
